INSERT INTO heritages (id, name_ja, name_en, country_ja, country_en, region, category, inscription_year, latitude, longitude, short_description_ja, memory_tip_ja, tags, unesco_criteria, official_url, unesco_url, source_urls, image_url, image_attribution, exam_importance) VALUES (660, '法隆寺地域の仏教建造物', 'Buddhist Monuments in the Horyu-ji Area', '日本', 'Japan', 'Asia and the Pacific', 'Cultural', 1993, 34.6145, 135.7344, '世界最古の木造建築群を含む法隆寺の仏教建造物群。聖徳太子ゆかりの寺院。', '日本初の世界遺産の一つ。「世界最古の木造建築」がキーワード。登録基準(i)(ii)(iv)(vi)。', '日本初,木造建築,奈良,聖徳太子,飛鳥時代', '(i)(ii)(iv)(vi)', 'http://www.horyuji.or.jp/', 'https://whc.unesco.org/en/list/660', 'https://www.bunka.go.jp/seisaku/bunkazai/shokai/sekai_isan/ichiran/', 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/e5/Horyu-ji08s3200.jpg/640px-Horyu-ji08s3200.jpg', '663highland, CC BY 2.5, via Wikimedia Commons', 5) ON CONFLICT (id) DO UPDATE SET name_ja=EXCLUDED.name_ja, name_en=EXCLUDED.name_en, country_ja=EXCLUDED.country_ja, country_en=EXCLUDED.country_en, region=EXCLUDED.region, category=EXCLUDED.category, inscription_year=EXCLUDED.inscription_year, latitude=EXCLUDED.latitude, longitude=EXCLUDED.longitude, short_description_ja=EXCLUDED.short_description_ja, memory_tip_ja=EXCLUDED.memory_tip_ja, tags=EXCLUDED.tags, unesco_criteria=EXCLUDED.unesco_criteria, official_url=EXCLUDED.official_url, unesco_url=EXCLUDED.unesco_url, source_urls=EXCLUDED.source_urls, image_url=EXCLUDED.image_url, image_attribution=EXCLUDED.image_attribution, exam_importance=EXCLUDED.exam_importance;
INSERT INTO heritages (id, name_ja, name_en, country_ja, country_en, region, category, inscription_year, latitude, longitude, short_description_ja, memory_tip_ja, tags, unesco_criteria, official_url, unesco_url, source_urls, image_url, image_attribution, exam_importance) VALUES (659, '姫路城', 'Himeji-jo', '日本', 'Japan', 'Asia and the Pacific', 'Cultural', 1993, 34.8394, 134.6939, '白鷺城とも呼ばれる日本を代表する城郭建築。木造城郭の最高傑作。', '日本初の世界遺産の一つ。「白鷺城」の別名。日本の城郭建築の最高傑作。登録基準(i)(iv)。', '日本初,城郭,兵庫,白鷺城', '(i)(iv)', 'https://www.city.himeji.lg.jp/castle/', 'https://whc.unesco.org/en/list/661', 'https://www.bunka.go.jp/seisaku/bunkazai/shokai/sekai_isan/ichiran/', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c9/Himeji_castle_in_may_2015.jpg/640px-Himeji_castle_in_may_2015.jpg', 'Oren Rozen, CC BY-SA 4.0, via Wikimedia Commons', 5) ON CONFLICT (id) DO UPDATE SET name_ja=EXCLUDED.name_ja, name_en=EXCLUDED.name_en, country_ja=EXCLUDED.country_ja, country_en=EXCLUDED.country_en, region=EXCLUDED.region, category=EXCLUDED.category, inscription_year=EXCLUDED.inscription_year, latitude=EXCLUDED.latitude, longitude=EXCLUDED.longitude, short_description_ja=EXCLUDED.short_description_ja, memory_tip_ja=EXCLUDED.memory_tip_ja, tags=EXCLUDED.tags, unesco_criteria=EXCLUDED.unesco_criteria, official_url=EXCLUDED.official_url, unesco_url=EXCLUDED.unesco_url, source_urls=EXCLUDED.source_urls, image_url=EXCLUDED.image_url, image_attribution=EXCLUDED.image_attribution, exam_importance=EXCLUDED.exam_importance;
INSERT INTO heritages (id, name_ja, name_en, country_ja, country_en, region, category, inscription_year, latitude, longitude, short_description_ja, memory_tip_ja, tags, unesco_criteria, official_url, unesco_url, source_urls, image_url, image_attribution, exam_importance) VALUES (662, '屋久島', 'Yakushima', '日本', 'Japan', 'Asia and the Pacific', 'Natural', 1993, 30.35, 130.5, '樹齢数千年の屋久杉が生育する亜熱帯から亜寒帯までの植生の垂直分布が見られる島。', '日本初の自然遺産の一つ。縄文杉(樹齢7200年)と植生の垂直分布がポイント。登録基準(vii)(ix)。', '日本初,自然遺産,鹿児島,屋久杉,縄文杉', '(vii)(ix)', NULL, 'https://whc.unesco.org/en/list/662', 'https://www.bunka.go.jp/seisaku/bunkazai/shokai/sekai_isan/ichiran/', 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d8/Yakushima_Jomon_Sugi_2009.jpg/640px-Yakushima_Jomon_Sugi_2009.jpg', 'Yosemite, CC BY-SA 3.0, via Wikimedia Commons', 5) ON CONFLICT (id) DO UPDATE SET name_ja=EXCLUDED.name_ja, name_en=EXCLUDED.name_en, country_ja=EXCLUDED.country_ja, country_en=EXCLUDED.country_en, region=EXCLUDED.region, category=EXCLUDED.category, inscription_year=EXCLUDED.inscription_year, latitude=EXCLUDED.latitude, longitude=EXCLUDED.longitude, short_description_ja=EXCLUDED.short_description_ja, memory_tip_ja=EXCLUDED.memory_tip_ja, tags=EXCLUDED.tags, unesco_criteria=EXCLUDED.unesco_criteria, official_url=EXCLUDED.official_url, unesco_url=EXCLUDED.unesco_url, source_urls=EXCLUDED.source_urls, image_url=EXCLUDED.image_url, image_attribution=EXCLUDED.image_attribution, exam_importance=EXCLUDED.exam_importance;
