INSERT INTO heritages (id, name_ja, name_en, country_ja, country_en, region, category, inscription_year, latitude, longitude, short_description_ja, memory_tip_ja, tags, unesco_criteria, official_url, unesco_url, source_urls, image_url, image_attribution, exam_importance) VALUES (1094, '知床', 'Shiretoko', '日本', 'Japan', 'Asia and the Pacific', 'Natural', 2005, 44.08, 145.15, '海と陸の生態系の相互関係が見られる北海道の半島。流氷がもたらす豊かな生態系。', '海洋生態系と陸上生態系の相互作用。流氷=アイスアルジー→食物連鎖。登録基準(ix)(x)。', '自然遺産,北海道,知床,流氷,生態系', '(ix)(x)', NULL, 'https://whc.unesco.org/en/list/1193', 'https://www.bunka.go.jp/seisaku/bunkazai/shokai/sekai_isan/ichiran/', 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b6/Shiretoko_National_Park.jpg/640px-Shiretoko_National_Park.jpg', 'Public domain, via Wikimedia Commons', 5) ON CONFLICT (id) DO UPDATE SET name_ja=EXCLUDED.name_ja, name_en=EXCLUDED.name_en, country_ja=EXCLUDED.country_ja, country_en=EXCLUDED.country_en, region=EXCLUDED.region, category=EXCLUDED.category, inscription_year=EXCLUDED.inscription_year, latitude=EXCLUDED.latitude, longitude=EXCLUDED.longitude, short_description_ja=EXCLUDED.short_description_ja, memory_tip_ja=EXCLUDED.memory_tip_ja, tags=EXCLUDED.tags, unesco_criteria=EXCLUDED.unesco_criteria, official_url=EXCLUDED.official_url, unesco_url=EXCLUDED.unesco_url, source_urls=EXCLUDED.source_urls, image_url=EXCLUDED.image_url, image_attribution=EXCLUDED.image_attribution, exam_importance=EXCLUDED.exam_importance;
INSERT INTO heritages (id, name_ja, name_en, country_ja, country_en, region, category, inscription_year, latitude, longitude, short_description_ja, memory_tip_ja, tags, unesco_criteria, official_url, unesco_url, source_urls, image_url, image_attribution, exam_importance) VALUES (1246, '石見銀山遺跡とその文化的景観', 'Iwami Ginzan Silver Mine and its Cultural Landscape', '日本', 'Japan', 'Asia and the Pacific', 'Cultural', 2007, 35.1083, 132.4361, '16〜17世紀に世界の銀産出量の約3分の1を占めた銀山遺跡。環境に配慮した採掘。', '世界の銀の1/3を産出。環境に配慮した「自然と共生する鉱山」が評価ポイント。登録基準(ii)(iii)(v)。', '島根,銀山,文化的景観,鉱山', '(ii)(iii)(v)', NULL, 'https://whc.unesco.org/en/list/1246', 'https://www.bunka.go.jp/seisaku/bunkazai/shokai/sekai_isan/ichiran/', 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/ba/Iwami_Ginzan_Silver_Mine%2C_Ryugenji_Mabu_Mine_Shaft_001.JPG/640px-Iwami_Ginzan_Silver_Mine%2C_Ryugenji_Mabu_Mine_Shaft_001.JPG', '663highland, CC BY 2.5, via Wikimedia Commons', 5) ON CONFLICT (id) DO UPDATE SET name_ja=EXCLUDED.name_ja, name_en=EXCLUDED.name_en, country_ja=EXCLUDED.country_ja, country_en=EXCLUDED.country_en, region=EXCLUDED.region, category=EXCLUDED.category, inscription_year=EXCLUDED.inscription_year, latitude=EXCLUDED.latitude, longitude=EXCLUDED.longitude, short_description_ja=EXCLUDED.short_description_ja, memory_tip_ja=EXCLUDED.memory_tip_ja, tags=EXCLUDED.tags, unesco_criteria=EXCLUDED.unesco_criteria, official_url=EXCLUDED.official_url, unesco_url=EXCLUDED.unesco_url, source_urls=EXCLUDED.source_urls, image_url=EXCLUDED.image_url, image_attribution=EXCLUDED.image_attribution, exam_importance=EXCLUDED.exam_importance;
INSERT INTO heritages (id, name_ja, name_en, country_ja, country_en, region, category, inscription_year, latitude, longitude, short_description_ja, memory_tip_ja, tags, unesco_criteria, official_url, unesco_url, source_urls, image_url, image_attribution, exam_importance) VALUES (1277, '平泉—仏国土（浄土）を表す建築・庭園及び考古学的遺跡群', 'Hiraizumi – Temples, Gardens and Archaeological Sites Representing the Buddhist Pure Land', '日本', 'Japan', 'Asia and the Pacific', 'Cultural', 2011, 39.0014, 141.1067, '中尊寺金色堂を中心とする浄土思想に基づく建築群。奥州藤原氏の栄華を伝える。', '中尊寺金色堂が中心。奥州藤原氏。浄土思想を建築・庭園で表現。登録基準(ii)(vi)。', '岩手,平泉,中尊寺,浄土思想,奥州藤原氏', '(ii)(vi)', NULL, 'https://whc.unesco.org/en/list/1277', 'https://www.bunka.go.jp/seisaku/bunkazai/shokai/sekai_isan/ichiran/', 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b0/Konjikido-Ooido.jpg/640px-Konjikido-Ooido.jpg', 'Yanajin33, CC BY-SA 3.0, via Wikimedia Commons', 5) ON CONFLICT (id) DO UPDATE SET name_ja=EXCLUDED.name_ja, name_en=EXCLUDED.name_en, country_ja=EXCLUDED.country_ja, country_en=EXCLUDED.country_en, region=EXCLUDED.region, category=EXCLUDED.category, inscription_year=EXCLUDED.inscription_year, latitude=EXCLUDED.latitude, longitude=EXCLUDED.longitude, short_description_ja=EXCLUDED.short_description_ja, memory_tip_ja=EXCLUDED.memory_tip_ja, tags=EXCLUDED.tags, unesco_criteria=EXCLUDED.unesco_criteria, official_url=EXCLUDED.official_url, unesco_url=EXCLUDED.unesco_url, source_urls=EXCLUDED.source_urls, image_url=EXCLUDED.image_url, image_attribution=EXCLUDED.image_attribution, exam_importance=EXCLUDED.exam_importance;
INSERT INTO heritages (id, name_ja, name_en, country_ja, country_en, region, category, inscription_year, latitude, longitude, short_description_ja, memory_tip_ja, tags, unesco_criteria, official_url, unesco_url, source_urls, image_url, image_attribution, exam_importance) VALUES (1321, '小笠原諸島', 'Ogasawara Islands', '日本', 'Japan', 'Asia and the Pacific', 'Natural', 2011, 27.0833, 142.2, '東洋のガラパゴスと呼ばれる島々。独自の進化を遂げた固有種が多数生息。', '「東洋のガラパゴス」。適応放散による進化の証拠。固有種の宝庫。登録基準(ix)。', '自然遺産,東京,小笠原,固有種,適応放散', '(ix)', NULL, 'https://whc.unesco.org/en/list/1362', 'https://www.bunka.go.jp/seisaku/bunkazai/shokai/sekai_isan/ichiran/', 'https://upload.wikimedia.org/wikipedia/commons/thumb/7/73/Minamijima.jpg/640px-Minamijima.jpg', 'Public domain, via Wikimedia Commons', 5) ON CONFLICT (id) DO UPDATE SET name_ja=EXCLUDED.name_ja, name_en=EXCLUDED.name_en, country_ja=EXCLUDED.country_ja, country_en=EXCLUDED.country_en, region=EXCLUDED.region, category=EXCLUDED.category, inscription_year=EXCLUDED.inscription_year, latitude=EXCLUDED.latitude, longitude=EXCLUDED.longitude, short_description_ja=EXCLUDED.short_description_ja, memory_tip_ja=EXCLUDED.memory_tip_ja, tags=EXCLUDED.tags, unesco_criteria=EXCLUDED.unesco_criteria, official_url=EXCLUDED.official_url, unesco_url=EXCLUDED.unesco_url, source_urls=EXCLUDED.source_urls, image_url=EXCLUDED.image_url, image_attribution=EXCLUDED.image_attribution, exam_importance=EXCLUDED.exam_importance;
